@ReubenBond I've investigated this further and it is introduced in 1.5.1-beta.

Looking at the ```GrainReferenceConverter```, there is this function:

```csharp
    public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
        {
            var key = serializer.Deserialize<string>(reader);
            if (string.IsNullOrWhiteSpace(key)) return null;

            var result = GrainReference.FromKeyString(key, null);  // !!! <<  Shouldn't  IGrainReferenceConverter be used here?
             this.grainFactory.BindGrainReference(result);
            return Casters.GetOrAdd(objectType, CreateCasterDelegate)(result);
        }

```

update: this test reproduces the problem. It has nothing to do with generics.
```csharp
 public class GrainReferenceJsonStorageTests : HostedTestClusterEnsureDefaultStarted
    {
        public GrainReferenceJsonStorageTests(ITestOutputHelper output, DefaultClusterFixture fixture) : base(fixture)
        {
           
        }

        [Fact]
        public void CanRoundTripGrainReference()
        {
            var serializer = new OrleansStorageDefaultJsonSerializer(
                OrleansJsonSerializer.GetDefaultSerializerSettings(HostedCluster.SerializationManager,
                    HostedCluster.GrainFactory), "UseJsonFormat");
            var deserializer = new OrleansStorageDefaultJsonDeserializer(
                OrleansJsonSerializer.GetDefaultSerializerSettings(HostedCluster.SerializationManager,
                    HostedCluster.GrainFactory), "UseJsonFormat");


            var grain = HostedCluster.GrainFactory.GetGrain<ISimpleGrain>(GetRandomGrainId());
            var input = new GenericGrainReferenceHolder()
            {
                Reference = grain as GrainReference //this is how its done in PubSubSubscriptionState constructor
            };
        
            var json = serializer.Serialize(input);

            var output = (GenericGrainReferenceHolder)deserializer.Deserialize(json, typeof(GenericGrainReferenceHolder));

            Assert.Equal(input.Reference,output.Reference);
        }

        [Serializable]
        public class GenericGrainReferenceHolder
        {
            [JsonProperty]
            public GrainReference Reference { get; set; }
        }
    }
```

The offending line is

```
   private static GrainFactory.GrainReferenceCaster CreateCaster(Type grainReferenceType)
        {
            var interfaceType = grainReferenceType.GetTypeInfo().GetCustomAttribute<GrainReferenceAttribute>().TargetType;
            return GrainCasterFactory.CreateGrainReferenceCaster(interfaceType, grainReferenceType);
        }
```

The type does not have a GrainReferenceAttribute. Maybe because it is explicitly downcasted to a GrainReference?
